using System.Net.Http;
using System.Text.Json;
using Xunit;

namespace DotNetBoostSample.Tests.Integration;

/// <summary>
/// The OpenAPI document describes the bodies this API actually sends.
///
/// <para><b>Why this needs a test at all.</b> <c>GET /api/settings/branding</c> is shaped by
/// <c>BrandingProjector</c>, so its body is not the stored group — it carries those three settings
/// plus <c>resolved</c>, <c>images</c> and <c>logo</c>. The endpoint is generated by
/// DotNetBoost.Settings, which declares the 200 from the projector's own
/// <c>ISettingProjector&lt;BrandingSettings, BrandingResponse&gt;</c>. That is three moving parts
/// away from this repository — a library version, a declaration, and a response built by
/// reflection — and the document is the one output nothing else in the suite reads. This application
/// used to correct that schema itself with an operation transformer; the assertions did not change
/// when the library took it over, which is the point of writing them against a real response rather
/// than a list.</para>
///
/// <para>The assertions compare the document against a real response rather than against a list
/// written here. A list would be a third copy of the shape, free to drift from both.</para>
/// </summary>
public abstract class OpenApiShapeTests(SampleApp app)
{
    [RequiresDockerFact]
    public async Task The_documented_branding_response_is_the_one_branding_sends()
    {
        var client = app.Client;

        // A logo, so `logo` is an object in the response and its fields can be compared too. The
        // group has no table and the attachment is the only record of it; see BrandingSettings.
        var file = await client.UploadAsync("/api/media", "documented-logo.png");

        await client.SendJsonCheckedAsync(HttpMethod.Post, $"/api/media/{file.Str("id")}/attachments", new
        {
            ownerEntityName = "Branding",
            ownerEntityId = "branding",
            role = "logo",
            replace = true
        });

        var document = await client.GetJsonAsync("/openapi/v1.json");
        var branding = await client.GetJsonAsync("/api/settings/branding");

        var documented = Documented(document, "/api/settings/branding");

        // The whole point: the published property names are the ones on the wire. Before the
        // transformer this was ["accentColor", "headerLogoSize", "storeName"] against a response
        // that also carries images, logo and resolved.
        Assert.Equal(branding.Keys().Order(), Properties(document, documented).Keys().Order());

        // And one level down, for the shape both the catalogue and branding describe files with.
        var logo = Properties(document, Properties(document, documented).GetProperty("logo"));

        Assert.Equal(branding.GetProperty("logo").Keys().Order(), logo.Keys().Order());

        var images = Properties(document,
            Properties(document, documented).GetProperty("images").GetProperty("items"));

        var attached = branding.GetProperty("images").EnumerateArray().First();

        Assert.Equal(attached.Keys().Order(), images.Keys().Order());

        // An attachment carries the two fields a bare file cannot, which is the difference between
        // the two records in Endpoints/AttachedFiles.cs.
        Assert.Contains("role", images.Keys());
        Assert.DoesNotContain("role", logo.Keys());
    }

    /// <summary>
    /// The WRITE is still the stored group, and the document still says so. A projector shapes the
    /// read only — publishing the read's shape as the request body would advertise a POST this API
    /// refuses, with `images` and `resolved` in it.
    /// </summary>
    [RequiresDockerFact]
    public async Task The_documented_branding_request_is_the_stored_group_alone()
    {
        var document = await app.Client.GetJsonAsync("/openapi/v1.json");

        var body = document
            .GetProperty("paths").GetProperty("/api/settings/branding")
            .GetProperty("post").GetProperty("requestBody")
            .GetProperty("content").GetProperty("application/json").GetProperty("schema");

        Assert.Equal(
            ["accentColor", "headerLogoSize", "storeName"],
            Properties(document, body).Keys().Order());
    }

    /// <summary>The 200 schema of a path's GET, with any <c>$ref</c> left for the caller to follow.</summary>
    private static JsonElement Documented(JsonElement document, string path) =>
        document
            .GetProperty("paths").GetProperty(path)
            .GetProperty("get").GetProperty("responses").GetProperty("200")
            .GetProperty("content").GetProperty("application/json").GetProperty("schema");

    /// <summary>
    /// A schema's <c>properties</c>, unwrapping a nullable union and following a <c>$ref</c> into
    /// <c>components</c> first.
    ///
    /// <para>All three forms are valid and which one comes out is the generator's choice — a type it
    /// put in components is referenced, one it inlined is not, and a property that may be
    /// <c>null</c> is a <c>oneOf</c> over <c>null</c> and the type. A test that read only one would
    /// break on a change that means nothing.</para>
    ///
    /// <para>That is not hypothetical here: when this application declared the schema itself the
    /// shape was inlined and <c>logo</c> was a bare object — documented as always present, which it
    /// is not. Declaring it through the projector instead publishes
    /// <c>oneOf: [null, $ref AttachedFile]</c>, so the document now says the logo may be absent.
    /// The nullability improved by moving the declaration into the library, and this helper is what
    /// lets the assertions stay the same across both.</para>
    /// </summary>
    private static JsonElement Properties(JsonElement document, JsonElement schema)
    {
        foreach (var union in (string[])["oneOf", "anyOf"])
        {
            if (!schema.TryGetProperty(union, out var branches)) continue;

            // The one branch that is not the null marker. Several non-null branches would be a
            // polymorphic schema, which nothing here produces — and Single says so if that changes.
            schema = branches.EnumerateArray().Single(b =>
                !b.TryGetProperty("type", out var type) || type.GetString() != "null");
        }

        if (schema.TryGetProperty("$ref", out var reference))
        {
            var name = reference.GetString()!.Split('/')[^1];
            schema = document.GetProperty("components").GetProperty("schemas").GetProperty(name);
        }

        return schema.GetProperty("properties");
    }
}

/// <summary>
/// <inheritdoc cref="OpenApiShapeTests" path="/summary/node()[1]"/>
/// <para>Run in the mode the sample ships in: every language is a translation row.</para>
/// </summary>
[Collection(SampleAppCollection.Name)]
public sealed class OpenApiShapeTestsInDefaultMode(SampleApp app) : OpenApiShapeTests(app);

/// <summary>
/// The same assertions about the generated document, against the same application booted with
/// <c>MultiLingualOptions.BaseLanguage = "en"</c>.
///
/// <para>Running them twice rather than reasoning about which ones could care is the point: the
/// mode moves content between a column and a translation row, and the claim this sample makes is
/// that no caller can tell. A claim like that is worth more re-run than re-read.</para>
/// </summary>
[Collection(BaseLanguageSampleAppCollection.Name)]
public sealed class OpenApiShapeTestsInBaseLanguageMode(BaseLanguageSampleApp app) : OpenApiShapeTests(app);
